        [Fact]
        public void Test_do_not_clamp_height_of_absolute_node_to_height_of_its_overflow_hidden_parent()
        {
            YogaConfig config = new YogaConfig();

            YogaNode root = new YogaNode(config);
            root.FlexDirection = YogaFlexDirection.Row;
            root.Overflow = YogaOverflow.Hidden;
            root.Width = YogaValue.Point(50);
            root.Height = YogaValue.Point(50);

            YogaNode root_child0 = new YogaNode(config);
            root_child0.PositionType = YogaPositionType.Absolute;
            root_child0.SetPosition(YogaEdge.Start, YogaValue.Point(0));
            root_child0.SetPosition(YogaEdge.Top, YogaValue.Point(0));
            root.Insert(0, root_child0);

            YogaNode root_child0_child0 = new YogaNode(config);
            root_child0_child0.Width = YogaValue.Point(100);
            root_child0_child0.Height = YogaValue.Point(100);
            root_child0.Insert(0, root_child0_child0);
            root.StyleDirection = YogaDirection.LTR;
            root.CalculateLayout();

            Assert.Equal(0f, root.LayoutX);
            Assert.Equal(0f, root.LayoutY);
            Assert.Equal(50f, root.LayoutWidth);
            Assert.Equal(50f, root.LayoutHeight);

            Assert.Equal(0f, root_child0.LayoutX);
            Assert.Equal(0f, root_child0.LayoutY);
            Assert.Equal(100f, root_child0.LayoutWidth);
            Assert.Equal(100f, root_child0.LayoutHeight);

            Assert.Equal(0f, root_child0_child0.LayoutX);
            Assert.Equal(0f, root_child0_child0.LayoutY);
            Assert.Equal(100f, root_child0_child0.LayoutWidth);
            Assert.Equal(100f, root_child0_child0.LayoutHeight);

            root.StyleDirection = YogaDirection.RTL;
            root.CalculateLayout();

            Assert.Equal(0f, root.LayoutX);
            Assert.Equal(0f, root.LayoutY);
            Assert.Equal(50f, root.LayoutWidth);
            Assert.Equal(50f, root.LayoutHeight);

            Assert.Equal(-50f, root_child0.LayoutX);
            Assert.Equal(0f, root_child0.LayoutY);
            Assert.Equal(100f, root_child0.LayoutWidth);
            Assert.Equal(100f, root_child0.LayoutHeight);

            Assert.Equal(0f, root_child0_child0.LayoutX);
            Assert.Equal(0f, root_child0_child0.LayoutY);
            Assert.Equal(100f, root_child0_child0.LayoutWidth);
            Assert.Equal(100f, root_child0_child0.LayoutHeight);
        }

        [Fact]
        public void Test_absolute_layout_within_border()
        {
            YogaConfig config = new YogaConfig();

            YogaNode root = new YogaNode(config);
            root.SetMargin(YogaEdge.Left, YogaValue.Point(10));
            root.SetMargin(YogaEdge.Top, YogaValue.Point(10));
            root.SetMargin(YogaEdge.Right, YogaValue.Point(10));
            root.SetMargin(YogaEdge.Bottom, YogaValue.Point(10));
            root.SetPadding(YogaEdge.Left, YogaValue.Point(10));
            root.SetPadding(YogaEdge.Top, YogaValue.Point(10));
            root.SetPadding(YogaEdge.Right, YogaValue.Point(10));
            root.SetPadding(YogaEdge.Bottom, YogaValue.Point(10));
            root.SetBorder(YogaEdge.Left, 10);
            root.SetBorder(YogaEdge.Top, 10);
            root.SetBorder(YogaEdge.Right, 10);
            root.SetBorder(YogaEdge.Bottom, 10);
            root.Width = YogaValue.Point(100);
            root.Height = YogaValue.Point(100);

            YogaNode root_child0 = new YogaNode(config);
            root_child0.PositionType = YogaPositionType.Absolute;
            root_child0.SetPosition(YogaEdge.Left, YogaValue.Point(0));
            root_child0.SetPosition(YogaEdge.Top, YogaValue.Point(0));
            root_child0.Width = YogaValue.Point(50);
            root_child0.Height = YogaValue.Point(50);
            root.Insert(0, root_child0);

            YogaNode root_child1 = new YogaNode(config);
            root_child1.PositionType = YogaPositionType.Absolute;
            root_child1.SetPosition(YogaEdge.Right, YogaValue.Point(0));
            root_child1.SetPosition(YogaEdge.Bottom, YogaValue.Point(0));
            root_child1.Width = YogaValue.Point(50);
            root_child1.Height = YogaValue.Point(50);
            root.Insert(1, root_child1);

            YogaNode root_child2 = new YogaNode(config);
            root_child2.PositionType = YogaPositionType.Absolute;
            root_child2.SetPosition(YogaEdge.Left, YogaValue.Point(0));
            root_child2.SetPosition(YogaEdge.Top, YogaValue.Point(0));
            root_child2.SetMargin(YogaEdge.Left, YogaValue.Point(10));
            root_child2.SetMargin(YogaEdge.Top, YogaValue.Point(10));
            root_child2.SetMargin(YogaEdge.Right, YogaValue.Point(10));
            root_child2.SetMargin(YogaEdge.Bottom, YogaValue.Point(10));
            root_child2.Width = YogaValue.Point(50);
            root_child2.Height = YogaValue.Point(50);
            root.Insert(2, root_child2);

            YogaNode root_child3 = new YogaNode(config);
            root_child3.PositionType = YogaPositionType.Absolute;
            root_child3.SetPosition(YogaEdge.Right, YogaValue.Point(0));
            root_child3.SetPosition(YogaEdge.Bottom, YogaValue.Point(0));
            root_child3.SetMargin(YogaEdge.Left, YogaValue.Point(10));
            root_child3.SetMargin(YogaEdge.Top, YogaValue.Point(10));
            root_child3.SetMargin(YogaEdge.Right, YogaValue.Point(10));
            root_child3.SetMargin(YogaEdge.Bottom, YogaValue.Point(10));
            root_child3.Width = YogaValue.Point(50);
            root_child3.Height = YogaValue.Point(50);
            root.Insert(3, root_child3);
            root.StyleDirection = YogaDirection.LTR;
            root.CalculateLayout();

            Assert.Equal(10f, root.LayoutX);
            Assert.Equal(10f, root.LayoutY);
            Assert.Equal(100f, root.LayoutWidth);
            Assert.Equal(100f, root.LayoutHeight);

            Assert.Equal(10f, root_child0.LayoutX);
            Assert.Equal(10f, root_child0.LayoutY);
            Assert.Equal(50f, root_child0.LayoutWidth);
            Assert.Equal(50f, root_child0.LayoutHeight);

            Assert.Equal(40f, root_child1.LayoutX);
            Assert.Equal(40f, root_child1.LayoutY);
            Assert.Equal(50f, root_child1.LayoutWidth);
            Assert.Equal(50f, root_child1.LayoutHeight);

            Assert.Equal(20f, root_child2.LayoutX);
            Assert.Equal(20f, root_child2.LayoutY);
            Assert.Equal(50f, root_child2.LayoutWidth);
            Assert.Equal(50f, root_child2.LayoutHeight);

            Assert.Equal(30f, root_child3.LayoutX);
            Assert.Equal(30f, root_child3.LayoutY);
            Assert.Equal(50f, root_child3.LayoutWidth);
            Assert.Equal(50f, root_child3.LayoutHeight);

            root.StyleDirection = YogaDirection.RTL;
            root.CalculateLayout();

            Assert.Equal(10f, root.LayoutX);
            Assert.Equal(10f, root.LayoutY);
            Assert.Equal(100f, root.LayoutWidth);
            Assert.Equal(100f, root.LayoutHeight);

            Assert.Equal(10f, root_child0.LayoutX);
            Assert.Equal(10f, root_child0.LayoutY);
            Assert.Equal(50f, root_child0.LayoutWidth);
            Assert.Equal(50f, root_child0.LayoutHeight);

            Assert.Equal(40f, root_child1.LayoutX);
            Assert.Equal(40f, root_child1.LayoutY);
            Assert.Equal(50f, root_child1.LayoutWidth);
            Assert.Equal(50f, root_child1.LayoutHeight);

            Assert.Equal(20f, root_child2.LayoutX);
            Assert.Equal(20f, root_child2.LayoutY);
            Assert.Equal(50f, root_child2.LayoutWidth);
            Assert.Equal(50f, root_child2.LayoutHeight);

            Assert.Equal(30f, root_child3.LayoutX);
            Assert.Equal(30f, root_child3.LayoutY);
            Assert.Equal(50f, root_child3.LayoutWidth);
            Assert.Equal(50f, root_child3.LayoutHeight);
        }

        [Fact]
        public void Test_absolute_layout_align_items_and_justify_content_center()
        {
            YogaConfig config = new YogaConfig();

            YogaNode root = new YogaNode(config);
            root.JustifyContent = YogaJustify.Center;
            root.AlignItems = YogaAlign.Center;
            root.FlexGrow = 1;
            root.Width = YogaValue.Point(110);
            root.Height = YogaValue.Point(100);

            YogaNode root_child0 = new YogaNode(config);
            root_child0.PositionType = YogaPositionType.Absolute;
            root_child0.Width = YogaValue.Point(60);
            root_child0.Height = YogaValue.Point(40);
            root.Insert(0, root_child0);
            root.StyleDirection = YogaDirection.LTR;
            root.CalculateLayout();

            Assert.Equal(0f, root.LayoutX);
            Assert.Equal(0f, root.LayoutY);
            Assert.Equal(110f, root.LayoutWidth);
            Assert.Equal(100f, root.LayoutHeight);

            Assert.Equal(25f, root_child0.LayoutX);
            Assert.Equal(30f, root_child0.LayoutY);
            Assert.Equal(60f, root_child0.LayoutWidth);
            Assert.Equal(40f, root_child0.LayoutHeight);

            root.StyleDirection = YogaDirection.RTL;
            root.CalculateLayout();

            Assert.Equal(0f, root.LayoutX);
            Assert.Equal(0f, root.LayoutY);
            Assert.Equal(110f, root.LayoutWidth);
            Assert.Equal(100f, root.LayoutHeight);

            Assert.Equal(25f, root_child0.LayoutX);
            Assert.Equal(30f, root_child0.LayoutY);
            Assert.Equal(60f, root_child0.LayoutWidth);
            Assert.Equal(40f, root_child0.LayoutHeight);
        }

